    PromptInspectorActivityView: {
      additionalProperties: false,
      description:
        'The Inspector\'s real projection of the frozen activity snapshot.\n\nEvery field is a fact the fragment was built from; nothing here is recomputed from a\nsecond read, so "the Inspector and the request body agree" is structural rather than a\nproperty someone has to remember to maintain.',
      properties: {
        body_hash: {
          $ref: '#/$defs/ContentHash',
          description:
            'The content hash of the exact body that became the fragment. It is what makes "the\nInspector shows the bytes that were sent" checkable rather than asserted.',
        },
        coverage: {
          $ref: '#/$defs/ActivityCoverageState',
          description: "Coverage of this snapshot against the reader's scope.",
        },
        fragment_present: {
          description: 'Whether an activity fragment was placed in the request at all.',
          type: 'boolean',
        },
        omitted: {
          description: 'Rows omitted for any reason, summed across the coverage counters.',
          minimum: 0,
          type: 'integer',
          maximum: 9007199254740991,
        },
        revision: { $ref: '#/$defs/Revision', description: 'The index revision at that instant.' },
        rows_in_scope: {
          description: "Rows in the reader's scope before any cap.",
          minimum: 0,
          type: 'integer',
          maximum: 9007199254740991,
        },
        rows_shown: {
          description: 'Rows the model actually saw.',
          minimum: 0,
          type: 'integer',
          maximum: 4294967295,
        },
        runtime_instance_id: {
          $ref: '#/$defs/RuntimeInstanceId',
          description: 'The runtime the snapshot came from.',
        },
        sampled_at: {
          $ref: '#/$defs/UtcTimestamp',
          description: 'The instant the index was sampled.',
        },
        truncated: {
          description: 'True when a body was cut to fit its byte bound.',
          type: 'boolean',
        },
      },
      required: [
        'sampled_at',
        'runtime_instance_id',
        'revision',
        'coverage',
        'rows_shown',
        'rows_in_scope',
        'omitted',
        'truncated',
        'body_hash',
        'fragment_present',
      ],
      type: 'object',
    },
    ActivityCoverageState: {
      description: 'Why the index is reporting less than everything.',
      oneOf: [
        {
          const: 'complete',
          description: 'Every fact the publishers offered was recorded.',
          type: 'string',
        },
        {
          const: 'partial',
          description:
            'Some facts were dropped, refused or truncated. The exact counts are beside\nthis state and are never zero.',
          type: 'string',
        },
        {
          const: 'unavailable',
          description: 'The index could not answer at all. This is not "nothing is running".',
          type: 'string',
        },
      ],
    },
